<?php include "db.php";if(!isset($_SESSION['user_id'])){header("Location: login.php");exit();}$uid=(int)$_SESSION['user_id'];if(isset($_GET['cancel'])){$id=(int)$_GET['cancel'];$stmt=mysqli_prepare($conn,"UPDATE bookings SET status='Cancelled' WHERE id=? AND user_id=? AND status='Booked'");mysqli_stmt_bind_param($stmt,"ii",$id,$uid);mysqli_stmt_execute($stmt);header("Location: my_bookings.php");exit();}$stmt=mysqli_prepare($conn,"SELECT bookings.*,buses.bus_name,buses.source,buses.destination,buses.travel_date,buses.departure_time FROM bookings JOIN buses ON bookings.bus_id=buses.id WHERE bookings.user_id=? ORDER BY bookings.id DESC");mysqli_stmt_bind_param($stmt,"i",$uid);mysqli_stmt_execute($stmt);$rows=mysqli_stmt_get_result($stmt);?>
<!DOCTYPE html><html><head><title>My Tickets</title><link rel="stylesheet" href="style.css"></head><body><header><h1>GoBus</h1><nav><a href="index.php">Home</a><a href="buses.php">Find Buses</a><a href="dashboard.php">Dashboard</a><a href="logout.php">Logout</a></nav></header><div class="container"><h2>My Ticket History</h2><?php if(isset($_GET['success']))echo '<p class="message">Ticket booked successfully.</p>'; ?><table><tr><th>ID</th><th>Bus</th><th>Route</th><th>Date/time</th><th>Passenger</th><th>Seat</th><th>Fare</th><th>Status</th><th>Action</th></tr><?php while($b=mysqli_fetch_assoc($rows)){?><tr><td><?php echo $b['id']; ?></td><td><?php echo htmlspecialchars($b['bus_name']); ?></td><td><?php echo htmlspecialchars($b['source'].' → '.$b['destination']); ?></td><td><?php echo $b['travel_date'].' '.$b['departure_time']; ?></td><td><?php echo htmlspecialchars($b['passenger_name']); ?></td><td><?php echo htmlspecialchars($b['seat_no']); ?></td><td>₹<?php echo number_format($b['total_price'],2); ?></td><td><?php echo htmlspecialchars($b['status']); ?></td><td><?php if($b['status']==='Booked')echo '<a href="my_bookings.php?cancel='.$b['id'].'" onclick="return confirm(\'Cancel this ticket?\')">Cancel</a>';else echo '-';?></td></tr><?php }?></table></div></body></html>